static float EaseOutCubic(float t) { t = t < 0 ? 0 : (t > 1 ? 1 : t); const float u = 1.0f - t; return 1.0f - u * u * u; }
static float EaseInOutCubic(float t) { t = t < 0 ? 0 : (t > 1 ? 1 : t); return t < 0.5f ? 4.0f * t * t * t : 1.0f - powf(-2.0f * t + 2.0f, 3.0f) * 0.5f; }
static float EaseOutBack(float t) { t = t < 0 ? 0 : (t > 1 ? 1 : t); const float c1 = 1.70158f, c3 = c1 + 1.0f; return 1.0f + c3 * powf(t - 1.0f, 3.0f) + c1 * powf(t - 1.0f, 2.0f); }

